    .support-section{padding:100px 0}.section-head{display:grid;grid-template-columns:1fr .8fr;gap:50px;align-items:end;margin-bottom:42px}.section-head p{margin:0;font-size:16px;line-height:1.75}.support-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.support-card{min-height:290px;padding:24px;display:flex;flex-direction:column;border:1px solid var(--line);border-radius:28px;background:var(--cream);box-shadow:0 20px 60px -46px rgba(6,26,21,.55);transition:.28s ease;cursor:pointer}.support-card:hover{transform:translateY(-5px);box-shadow:var(--shadow)}.support-card.active{background:var(--pine-900);color:white;border-color:var(--pine-900)}.support-number{width:44px;height:44px;display:grid;place-items:center;border-radius:16px;background:var(--acid);color:var(--pine-950);font-size:11px;font-weight:800}.support-card h3{font-family:var(--display);font-size:27px;line-height:1.02;margin:26px 0 11px}.support-card p{font-size:12px;line-height:1.65;color:rgba(22,35,30,.58);margin:0}.support-card.active p{color:rgba(255,255,255,.6)}.support-link{margin-top:auto;padding-top:22px;display:flex;justify-content:space-between;align-items:center;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.1em}.support-card.active .support-link{color:var(--acid)}
