r:pointer}.form-foot{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-top:24px}.consent{display:flex;gap:10px;align-items:flex-start;max-width:430px;font-size:10px;line-height:1.5;color:rgba(22,35,30,.54)}.consent input{margin-top:2px;accent-color:var(--pine-800)}
    .contact-sidebar{padding:25px;position:sticky;top:92px}.channel-list{display:grid;gap:10px}.channel{padding:17px;border:1px solid var(--line);border-radius:20px;background:var(--cream);display:grid;grid-template-columns:44px 1fr auto;gap:12px;align-items:center}.channel-icon{width:44px;height:44px;display:grid;place-items:center;border-radius:15px;background:var(--pine-900);color:var(--acid)}.channel small{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.13em;color:rgba(22,35,30,.42)}.channel strong{display:block;margin-top:4px;font-size:11px}.channel button,.channel a{border:0;background:none;color:var(--pine-700);font-size:9px;font-weight:800;cursor:pointer}.sidebar-divider{height:1px;background:var(--line);margin:22px 0}.hours h3,.quick-status h3{font-family:var(--display);font-size:24px;margin:0 0 14px}.hours-row{display:flex;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid var(--line);font-size:10px}.hours-row span:first-child{color:rgba(22,35,30,.54)}.hours-row.today{font-weight:800;color:var(--pine-900)}.hours-row.today span:first-child{color:var(--pine-900)}.quick-status{margin-top:24px;padding:20px;border-radius:24px;background:var(--pine-900);color:white}.quick-status p{font-size:10px;line-height:1.6;color:rgba(255,255,255,.6)}.status-line{display:flex;align-items:center;gap:8px;margin-top:12px;font-size:10px}.status-line i{width:7px;height:7px;border-radius:50%;background:var(--acid)}
    .location-section{padding:100px 0}.location-grid{display:grid;grid-template-columns:.65fr 1.15fr;gap:24px}.location-copy{padding:34px;border-radius:32px;background:var(--pine-900);color:white}.location-copy p{font-size:13px;line-height:1.72;color:rgba(255,255,255,.62)}.address-card{margin-top:28px;padding:18px;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(255,255,255,.05)}.address-card small{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.13em;color:rgba(255,255,255,.4)}.address-card strong{display:block;margin-top:7px;font-size:13px;line-height:1.5}.address-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.map-card{min-height:530px;position:relative;overflow:hidden;border-radius:34px;background:#abc8af}.map-card::before{content:'';position:absolute;inset:0;background:url('https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1800&q=86') center/cover;filter:saturate(.72) contrast(.9)}.map-overlay{position:absolute;inset:0;background:linear-gradient(135deg,rgba(6,26,21,.05),rgba(6,26,21,.52))}.map-route{position:absolute;inset:10% 9%;width:82%;height:80%}.map-route path{fill:none;stroke:var(--acid);stroke-width:3;stroke-linecap:round;stroke-dasharray:10 14;filter:drop-shadow(0 0 7px rgba(223,252,98,.5))}.map-route circle{fill:var(--acid)}.map-label{position:absolute;padding:10px 13px;border-radius:14px;background:rgba(6,26,21,.88);color:white;box-shadow:var(--shadow-dark);font-size:9px;font-weight:800}.map-label.main{left:56%;top:45%}.map-label.parking{left:17%;bottom:18%}.map-label.shuttle{right:8%;top:17%}.transport-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:18px}.transport{padding:16px;border:1px solid rgba(255,255,255,.11);border-radius:18px;background:rgba(255,255,255,.05)}.transport strong{display:block;font-size:11px}.transport span{display:block;margin-top:5px;font-size:9px;line-height:1.5;color:rgba(255,255,255,.48)}
    .faq-section{padding:100px 0;background:var(--pine-950);color:white}.faq-grid{display:grid;grid-template-columns:.65fr 1.05fr;gap:70px}.faq-intro{position:sticky;top:110px;height:max-content}.faq-intro p{font-size:13px;line-height:1.72;color:rgba(255,255,255,.58)}.faq-list{display:grid;gap:9px}.faq-item{border:1px solid rgba(255,255,255,.1);border-radius:20px;background:rgba(255,255,255,.04);overflow:hidden}.faq-q{width:100%;padding:19px 20px;display:flex;align-items:center;justify-content:space-between;gap:18px;border:0;background:none;color:white;text-align:left;cursor:pointer;font-size:12px;font-weight:700}.faq-q span:last-child{font-size:20px;color:var(--acid);transition:.25s}.faq-item.open .faq-q span:last-child{transform:rotate(45deg)}.faq-a{max-height:0;overflow:hidden;transition:max-height .35s ease}.faq-a p{margin:0;padding:0 20px 20px;font-size:11px;line-height:1.7;color:rgba(255,255,255,.58)}.faq-item.open .faq-a{max-height:220px}
