      $('#menuOpen')?.addEventListener('click',()=>setMenu(true));$('#menuClose')?.addEventListener('click',()=>setMenu(false));$('#menuBackdrop')?.addEventListener('click',()=>setMenu(false));
      function onScroll(){const y=scrollY;nav?.classList.toggle('scrolled',y>24);const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?Math.min(1,y/max):0})`}
      addEventListener('scroll',onScroll,{passive:true});onScroll();
      addEventListener('keydown',e=>{if(e.key==='Escape'){setMenu(false);closeModal();closeChat()}});

      const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(!reduce&&'IntersectionObserver'in window){const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(28px)'},{opacity:1,transform:'none'}],{duration:680,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards'});io.unobserve(entry.target)}}),{threshold:.12});$$('[data-reveal]').forEach(el=>io.observe(el))}else{$$('[data-reveal]').forEach(el=>{el.style.opacity=1;el.style.transform='none'})}

      function animatePath(path,marker,duration=2200){if(!path||!marker||reduce)return;const length=path.getTotalLength();path.style.strokeDasharray=String(length);path.style.strokeDashoffset=String(length);path.animate([{strokeDashoffset:length},{strokeDashoffset:0}],{duration,easing:'cubic-bezier(.2,.75,.2,1)',fill:'forwards',delay:250});const start=performance.now()+250;function move(t){const p=Math.max(0,Math.min(1,(t-start)/duration)),pt=path.getPointAtLength(length*p);marker.setAttribute('cx',pt.x);marker.setAttribute('cy',pt.y);if(p<1)requestAnimationFrame(move)}requestAnimationFrame(move)}
      animatePath($('#heroRoute'),$('#heroMarker'));animatePath($('#mapPath'),$('#mapMarker'),2600);

      const topics={
        bilete:{label:'Bilete & rezervări',title:'Cu ce te putem ajuta?',response:'Echipa de ticketing răspunde, de regulă, în maximum 4 ore în timpul programului.',modal:'Maximum 4 ore',dynamic:'<label for="bookingDate">Data rezervării <span style="font-weight:500;text-transform:none;letter-spacing:0">(opțional)</span></label><input class="input" id="bookingDate" name="bookingDate" type="date">'},
        vizita:{label:'Vizita ta',title:'Pregătim vizita împreună.',response:'Pentru întrebări despre acces, vreme și facilități răspundem, de regulă, în maximum 2 ore.',modal:'Maximum 2 ore',dynamic:'<label for="plannedVisitDate">Data planificată a vizitei</label><input class="input" id="plannedVisitDate" name="plannedVisitDate" type="date">'},
        grupuri:{label:'Grupuri & școli',title:'Spune-ne cum arată grupul.',response:'Un coordonator de grup revine cu detalii și ofertă în maximum o zi lucrătoare.',modal:'Maximum 1 zi lucrătoare',dynamic:'<label for="groupSize">Număr estimat de participanți</label><input class="input" id="groupSize" name="groupSize" type="number" min="10" placeholder="Ex. 32">'},
        parteneriate:{label:'Presă & parteneriate',title:'Construim contextul potrivit.',response:'Solicitările editoriale și de parteneriat primesc răspuns în maximum două zile lucrătoare.',modal:'Maximum 2 zile lucrătoare',dynamic:'<label for="organization">Organizație / publicație</label><input class="input" id="organization" name="organization" placeholder="Numele organizației">'}
      };
      let activeTopic='bilete';
      function setTopic(topic){if(!topics[topic])return;activeTopic=topic;$$('[data-topic]').forEach(b=>b.classList.toggle('active',b.dataset.topic===topic));const data=topics[topic];$('#topicPill').textContent=data.label;$('#formTitle').textContent=data.title;$('#responseTime').textContent=data.response;$('#dynamicField').innerHTML=data.dynamic;$('#mesaj').scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'})}
      $$('[data-topic]').forEach(btn=>btn.addEventListener('click',()=>setTopic(btn.dataset.topic)));

      const fileInput=$('#attachments'),fileList=$('#fileList');let files=[];
      fileInput?.addEventListener('change',()=>{files=[...fileInput.files].slice(0,5);renderFiles()});
      function renderFiles(){fileList.innerHTML='';files.forEach((file,index)=>{const chip=document.createElement('span');chip.className='file-chip';chip.innerHTML=`<span>${file.name}</span><button type="button" aria-label="Elimină ${file.name}">×</button>`;chip.querySelector('button').addEventListener('click',()=>{files.splice(index,1);renderFiles()});fileList.appendChild(chip)})}

      const toast=$('#toast');function showToast(text){toast.textContent=text;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2800)}
      $$('[data-copy]').forEach(el=>el.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(el.dataset.copy);showToast('Copiat în clipboard.')}catch{showToast(el.dataset.copy)}}));

      const success=$('#successModal');function openModal(){const n=`NV-SUP-${Math.floor(1000+Math.random()*9000)}`;$('#caseNumber').textContent=n;$('#modalResponse').textContent=topics[activeTopic].modal;success.classList.add('open');success.setAttribute('aria-hidden','false');body.classList.add('modal-open')}function closeModal(){success?.classList.remove('open');success?.setAttribute('aria-hidden','true');if(!$('#chatModal')?.classList.contains('open'))body.classList.remove('modal-open')}$$('[data-close-modal]').forEach(el=>el.addEventListener('click',closeModal));
      $('#contactForm')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.checkValidity()){form.reportValidity();return}openModal();form.reset();files=[];renderFiles()});

      const chat=$('#chatModal');function openChat(){chat.classList.add('open');chat.setAttribute('aria-hidden','false');body.classList.add('modal-open');setTimeout(()=>$('#chatText')?.focus(),300)}function closeChat(){chat?.classList.remove('open');chat?.setAttribute('aria-hidden','true');if(!success?.classList.contains('open'))body.classList.remove('modal-open')}$$('[data-open-chat]').forEach(el=>el.addEventListener('click',openChat));$$('[data-close-chat]').forEach(el=>el.addEventListener('click',closeChat));
      $('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();const input=$('#chatText'),text=input.value.trim();if(!text)return;const mine=document.createElement('div');mine.className='chat-message user';mine.textContent=text;$('#chatMessages').appendChild(mine);input.value='';setTimeout(()=>{const reply=document.createElement('div');reply.className='chat-message agent';reply.textContent='Am înțeles. Pentru această situație am nevoie de numărul comenzii sau data vizitei. Îl poți trimite aici.';$('#chatMessages').appendChild(reply);reply.scrollIntoView({behavior:'smooth',block:'nearest'})},700)});

      $$('.faq-q').forEach(btn=>btn.addEventListener('click',()=>{const item=btn.closest('.faq-item'),open=item.classList.contains('open');$$('.faq-item').forEach(i=>i.classList.remove('open'));if(!open)item.classList.add('open')}));
    })();
  </script>
</body>
</html>
